<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">router.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/page/:pageName&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, checkAccountOnlineStatus, renderPage)</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">;</span></span>
